/**
 * Fails fast, with a fix attached to every failure. The point is to never let a start die four
 * minutes into a Gradle build for something we could have seen in a hundred milliseconds.
 */

import { spawnResolved } from './command.mjs';
import { isPortListening } from './ports.mjs';
import { publishedProxyPort } from './proxy.mjs';
import { runEntryPoint } from './entrypoint.mjs';

const TOOLS = Object.freeze([
  {
    name: 'docker',
    args: ['--version'],
    fix: 'Install Docker Desktop: https://docs.docker.com/desktop/',
  },
  { name: 'node', args: ['--version'], fix: 'Install Node 24+ (nvm install 24).' },
  { name: 'pnpm', args: ['--version'], fix: 'Install pnpm 11+: npm i -g pnpm.' },
  { name: 'just', args: ['--version'], fix: 'Install just: brew install just.' },
]);

/**
 * The one process runner every module injects as `exec`. Returns instead of throwing, so callers
 * decide what a non-zero exit means — `docker network connect` on an already-connected network is
 * an expected failure, a failed `nginx -t` is not.
 */
export function run(command, args, options = {}) {
  return new Promise((resolve) => {
    const child = spawnResolved(command, args, {
      stdio: ['ignore', 'pipe', 'pipe'],
      env: options.env ?? process.env,
    });
    let stdout = '';
    let stderr = '';
    child.stdout.on('data', (chunk) => {
      stdout += chunk;
    });
    child.stderr.on('data', (chunk) => {
      stderr += chunk;
    });
    child.on('error', (error) => resolve({ code: 127, stdout: '', stderr: error.message }));
    child.on('close', (code) =>
      resolve({ code: code ?? 1, stdout: stdout.trim(), stderr: stderr.trim() }),
    );
  });
}

async function checkTool(tool, exec) {
  const { code, stdout } = await exec(tool.name, tool.args);
  if (code === 0) {
    return { name: tool.name, ok: true, detail: stdout, fix: null };
  } else {
    return { name: tool.name, ok: false, detail: 'not found', fix: tool.fix };
  }
}

async function checkDockerDaemon(exec) {
  const daemon = await exec('docker', ['info', '--format', '{{.ServerVersion}}']);
  if (daemon.code === 0) {
    return { name: 'docker daemon', ok: true, detail: `server ${daemon.stdout}`, fix: null };
  } else {
    return {
      name: 'docker daemon',
      ok: false,
      detail: 'not reachable',
      fix: 'Start Docker Desktop and wait for the whale to settle.',
    };
  }
}

async function checkProxyPort(proxyPort, exec) {
  // Our own shared urbo-proxy legitimately holding this port is the normal state for a second
  // worktree, not a conflict — but only when the port it actually publishes is the one we're
  // checking. Read the published host port rather than just "is it running", so a stale proxy
  // bound to some other port can't mask a genuine occupant of this one. `publishedProxyPort` is
  // the single home for this check — `proxy.mjs`'s `ensureProxy` needs the identical answer.
  const proxyPublishedPort = await publishedProxyPort({ exec });
  const proxyPublishesThisPort = proxyPublishedPort === proxyPort;
  if (proxyPublishesThisPort) {
    return {
      name: `port ${proxyPort}`,
      ok: true,
      detail: 'held by the shared urbo-proxy',
      fix: null,
    };
  } else {
    const listening = await isPortListening(proxyPort);
    if (listening) {
      return {
        name: `port ${proxyPort}`,
        ok: false,
        detail: 'in use',
        fix:
          `Something already listens on ${proxyPort}. Find it with ` +
          `\`lsof -nP -iTCP:${proxyPort} -sTCP:LISTEN\`, or start on another port with ` +
          `\`URBO_PROXY_PORT=8000 just up\`.`,
      };
    } else {
      return { name: `port ${proxyPort}`, ok: true, detail: 'free', fix: null };
    }
